previewCss:
.darma-loader-darma-b10-ripple-pool { --accent: var(--loader-color, #0ea5e9); --accent-2: var(--loader-secondary-color, #67e8f9); width: var(--loader-size, 84px); height: var(--loader-size, 84px); position: relative; display: grid; place-items: center; perspective: 260px; }
.darma-loader-darma-b10-ripple-pool span { position: absolute; width: 60%; height: 60%; border: calc(var(--loader-size, 84px) * .028) solid var(--accent); border-radius: 50%; opacity: 0; animation: darma-loader-darma-b10-ripple-pool-pool calc(var(--loader-speed, 1s) * 2.4) ease-out infinite; }
.darma-loader-darma-b10-ripple-pool span:nth-child(2) { border-color: var(--accent-2); animation-delay: calc(var(--loader-speed, 1s) * .8); }
.darma-loader-darma-b10-ripple-pool span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * 1.6); }
@keyframes darma-loader-darma-b10-ripple-pool-pool { 0% { transform: rotateX(62deg) scale(.15); opacity: 1; } 100% { transform: rotateX(62deg) scale(1.5); opacity: 0; } }

